        "Används också om fanatisk hängivenhet: von der Arbeit besessen sein, wie besessen arbeiten (arbeta som en besatt).",
        "Obs: besessen är också particip av besitzen (äga): Er hat ein Haus besessen. Det är en annan användning; kortet handlar om adjektivet besatt."
