      "translation": "dundra • åska • mullra",
      "explanation": [
        "Grundidé: donnern betyder dundra, mullra: om åska (es donnert — det åskar), om tungt buller (ett tåg, en lastbil, artilleri) eller om en hög röst.",
        "Former: donnert, donnerte, hat gedonnert. Om åska används opersonligt es: Es donnert. När verbet beskriver rörelse med buller används sein i perfekt: Der Zug ist über die Brücke gedonnert.",
        "I överförd betydelse betyder donnern att ryta högt och argt: Der Chef donnerte los."
      ],
      "examples": [
        {
          "de": "Es blitzt und donnert.",
          "lv": "Det blixtrar och åskar."
        },
        {
          "de": "Der Zug donnert über die Brücke.",
          "lv": "Tåget dundrar över bron."
        },
        {
          "de": "Die Lastwagen donnerten über die Straße.",
          "lv": "Lastbilarna dundrade fram på gatan."
        },
        {
          "de": "Der Chef donnerte: „Raus hier!“",
          "lv": "Chefen röt: ”Ut härifrån!”"
        }
      ],
      "comparison": [
        {
          "word": "grollen",
          "meaning": "mullra (på avstånd)",
          "example": "In der Ferne grollt es. – Det mullrar i fjärran."
        },
        {
          "word": "krachen",
          "meaning": "knaka, braka",
          "example": "Das Eis kracht unter den Füßen. – Isen knakar under fötterna."
        },
        {
          "word": "rumpeln",
          "meaning": "skramla, skumpa",
          "example": "Der Wagen rumpelt über die Steine. – Vagnen skramlar fram över stenarna."
        }
      ],
      "tip": [
        "Om åska heter det Es donnert; om blixt — Es blitzt.",
        "När det handlar om buller och rörelse kan donnern ta sein: ist gedonnert."
      ],
      "important": [
        "Om åska: es donnert med hat gedonnert, inte ist.",
        "Donnern handlar inte bara om åska: det kan också gälla tunga fordon eller en ilsken röst."
      ],
